import{_ as e,o as s,c as n,a2 as o}from"./chunks/framework.1C62pOns.js";const i="/pro-agent-hub-installer/capturas/es/apps-detalhe.png",l="/pro-agent-hub-installer/capturas/es/apps-designer.png",m=JSON.parse('{"title":"Apps","description":"","frontmatter":{},"headers":[],"relativePath":"es/interface/apps.md","filePath":"es/interface/apps.md","lastUpdated":1791171177000}'),r={name:"es/interface/apps.md"};function t(p,a,d,c,u,h){return s(),n("div",null,[...a[0]||(a[0]=[o('<h1 id="apps" tabindex="-1">Apps <a class="header-anchor" href="#apps" aria-label="Permalink to &quot;Apps&quot;">​</a></h1><p>Una <strong>App</strong> es una pantalla web construida dentro de la plataforma: formulario, panel, consulta. Tiene dirección propia, corre en un proceso aparte y puede abrirla quien no es usuario de ProAgentHub.</p><p>Es la respuesta a &quot;¿y cuando quien va a usarlo no debería entrar en ProAgentHub?&quot;.</p><h2 id="pestana-general" tabindex="-1">Pestaña General <a class="header-anchor" href="#pestana-general" aria-label="Permalink to &quot;Pestaña General&quot;">​</a></h2><p><img src="'+i+'" alt="apps-detalhe"></p><p>Descripción, icono (con el que aparece en el menú) y el <strong>slug</strong> — el trozo final de la dirección, <code>/a/&lt;slug&gt;</code>.</p><p>El <strong>modo de acceso</strong> decide quién entra:</p><ul><li><strong>Interno</strong> — exige usuario conectado, y respeta los grupos.</li><li><strong>Público</strong> — cualquiera con el enlace abre, sin login.</li></ul><div class="danger custom-block"><p class="custom-block-title">Público es público de verdad</p><p>En una App pública no existe usuario conectado: el código de la página no tiene a quién identificar, y todo lo que expone queda al alcance de quien tenga la dirección. No pongas detrás de una App pública nada que no publicarías en una página abierta.</p></div><h2 id="pestana-global" tabindex="-1">Pestaña Global <a class="header-anchor" href="#pestana-global" aria-label="Permalink to &quot;Pestaña Global&quot;">​</a></h2><p>CSS, JavaScript y un <strong>backend global</strong> compartidos por todas las páginas. Ahí están el tema, las utilidades y las funciones que varias páginas llaman.</p><h2 id="pestana-paginas" tabindex="-1">Pestaña Páginas <a class="header-anchor" href="#pestana-paginas" aria-label="Permalink to &quot;Pestaña Páginas&quot;">​</a></h2><p><img src="'+l+`" alt="apps-designer"></p><p>Cada página declara cómo está hecha, y eso es una elección por página:</p><ul><li><strong>Visual</strong> — montada arrastrando componentes en el diseñador. El HTML se genera a partir del árbol.</li><li><strong>Código</strong> — HTML escrito a mano.</li></ul><div class="warning custom-block"><p class="custom-block-title">No hay sincronía de vuelta</p><p>De lo visual sale HTML; del HTML <strong>no</strong> se rearma el árbol automáticamente. Existe una importación código→visual, pero es un paso único que activas a propósito, no un espejo. CSS y JS siguen editables a mano en los dos modos — es la salida de emergencia para lo que el diseñador no cubre.</p></div><h3 id="el-backend-de-la-pagina" tabindex="-1">El backend de la página <a class="header-anchor" href="#el-backend-de-la-pagina" aria-label="Permalink to &quot;El backend de la página&quot;">​</a></h3><p>Cada página tiene una pestaña de Python. <strong>Toda función de nivel superior cuyo nombre no empiece por <code>_</code> se convierte en un endpoint</strong>, llamable desde el JavaScript de la página con <code>proApp.call(&#39;nombre&#39;, {…})</code>.</p><p>No hay ruta ni decorador: la <strong>firma es el contrato</strong>. La misma lectura del código que monta la lista de funciones en pantalla valida los argumentos que llegan — por eso las dos no pueden divergir.</p><div class="tip custom-block"><p class="custom-block-title">El estado de módulo no sobrevive entre llamadas</p><p>El ámbito se rearma en cada petición, porque lleva al usuario conectado. Una variable global no guarda nada de una llamada a la siguiente. Lo que deba persistir va a <code>db</code>.</p></div><h3 id="los-datos-de-la-app" tabindex="-1">Los datos de la App <a class="header-anchor" href="#los-datos-de-la-app" aria-label="Permalink to &quot;Los datos de la App&quot;">​</a></h3><p>Cada App tiene una base MongoDB solo suya, <code>app_&lt;id&gt;</code> — por el número, no por el slug, de modo que renombrar la App nunca mueve los datos.</p><p>El código llega a ella por el <code>db</code> inyectado o por las mismas operaciones sueltas en el ámbito (<code>save</code>, <code>find</code>, <code>delete</code>…). No hay conexión que abrir, ni forma de direccionar la base de otra App. Ver <a href="/pro-agent-hub-installer/es/funcoes/app_backend">Backend de página</a>.</p><p>La base se <strong>borra junto con la App</strong>.</p><h3 id="archivos-enviados-por-la-pagina" tabindex="-1">Archivos enviados por la página <a class="header-anchor" href="#archivos-enviados-por-la-pagina" aria-label="Permalink to &quot;Archivos enviados por la página&quot;">​</a></h3><p>Arrastre el componente <strong>Archivo</strong> dentro de un formulario y póngale un nombre — ese nombre se convierte en el parámetro de la función de backend, como cualquier otro campo.</p><p>Al pulsar el botón que llama a la función, la página envía el archivo primero y le pasa a Python el <strong>identificador</strong>. En el backend:</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">def</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> receber</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(anexo: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">str</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) -&gt; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">str</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    dados </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> read_upload(anexo)          </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># los bytes</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    info </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> upload_info(anexo)           </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># nombre, tipo, tamaño, quién lo envió</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Recibí </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">{</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">info[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;filename&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">}</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> con </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">{len</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(dados)</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">}</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bytes&quot;</span></span></code></pre></div><p>Marcando <strong>Varios archivos</strong>, el parámetro llega como una lista de identificadores.</p><p>Los archivos viven en la <strong>base de la propia App</strong>, junto a sus datos — y valen las mismas reglas: no hay forma de alcanzar el archivo de otra App, <strong>desaparecen con la App</strong>, y <strong>no</strong> viajan en la exportación (que lleva la estructura, no los datos de producción). El tamaño máximo es el de la plataforma, en <code>PRO_AI_MAX_FILE_SIZE</code>.</p><p>Para listar o eliminar: <code>list_uploads()</code> y <code>delete_upload(id)</code>. Para ofrecer el archivo de vuelta en pantalla, <code>proApp.fileLink(id)</code> devuelve la dirección de descarga.</p><div class="warning custom-block"><p class="custom-block-title">En App público, el enlace de descarga solo sirve a quien lo envió</p><p>En un App <strong>interno</strong> vale la misma frontera de los datos: quien puede abrir el App puede descargar sus archivos. En un App <strong>público</strong>, no — el enlace solo entrega el archivo a quien lo envió estando autenticado, y lo que un visitante anónimo envía no sale por esa dirección de ninguna forma. Sin esto, un formulario público que recibe un documento personal entregaría el documento de un visitante a cualquier otro: el identificador del archivo es lo bastante secuencial como para adivinarlo.</p><p>Para mostrar ese contenido de todos modos, hágalo desde el <strong>backend de la página</strong> — <code>read_upload(id)</code> devuelve los bytes, y ahí es usted quien decide quién ve qué.</p></div><p>En un App público el envío también tiene <strong>cuota por visitante</strong> (por defecto, 10 archivos o 100 MB cada 10 minutos). Quien la supere recibe un aviso para intentarlo más tarde: es la única puerta de la plataforma en la que alguien sin registro escribe en la base de datos, y sin cuota un solo visitante llenaría el disco de la instalación.</p><p>El recuento se guarda <strong>en la memoria de cada réplica</strong> del servicio que publica las Apps, y la instalación por defecto levanta dos: el techo que la instalación aplica es el doble del número configurado. Si el límite tiene que ser exacto, levanta una sola réplica o ajusta el valor.</p><h2 id="pestana-vista-previa" tabindex="-1">Pestaña Vista previa <a class="header-anchor" href="#pestana-vista-previa" aria-label="Permalink to &quot;Pestaña Vista previa&quot;">​</a></h2><p>Ejecuta la App tal como quedará, incluso con el contenido aún sin guardar. Es el mismo renderizador que sirve la App publicada, así que lo que ves es lo que va a salir.</p><p>La vista previa corre dentro de un <code>iframe</code> aislado, sin acceso al origen del hub — el JavaScript que escribes no ve la sesión de quien está construyendo.</p><h2 id="pestana-versiones-y-publicacion" tabindex="-1">Pestaña Versiones y publicación <a class="header-anchor" href="#pestana-versiones-y-publicacion" aria-label="Permalink to &quot;Pestaña Versiones y publicación&quot;">​</a></h2><p>Una versión es la foto de la <strong>App entera</strong> — cabecera y todas las páginas. Publicar congela una de esas versiones, y es ella la que responde en <code>/a/&lt;slug&gt;</code>.</p><p><strong>Editar el borrador no cambia lo que está en el aire.</strong> Solo publicar de nuevo lo cambia. Es lo que permite tocar con calma una pantalla en uso.</p><h2 id="donde-aparecen-las-apps" tabindex="-1">Dónde aparecen las Apps <a class="header-anchor" href="#donde-aparecen-las-apps" aria-label="Permalink to &quot;Dónde aparecen las Apps&quot;">​</a></h2><p>Para quien la usa, una App publicada es <strong>un elemento del menú lateral</strong>, y no una línea en una pantalla de listado. Quien construye ve la lista en Apps; quien consume ve solo el nombre y el icono que le pusiste.</p>`,42)])])}const b=e(r,[["render",t]]);export{m as __pageData,b as default};
